//! Includes the Rust declarations of FFmpeg from `ffmpeg_decoders_bindings.rs`,
//! generated by scripts/build.sh and named by `FFMPEG_DECODERS_BINDINGS`.

// A build script reports failure by panicking; the message stops the build.
#![allow(clippy::expect_used, clippy::unwrap_used)]

use std::env;
use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-env-changed=FFMPEG_DECODERS_BINDINGS");
    let out =
        PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR is set by cargo"))
            .join("bindings.rs");
    let bindings = env::var("FFMPEG_DECODERS_BINDINGS")
        .expect("FFMPEG_DECODERS_BINDINGS names the generated bindings");
    println!("cargo:rerun-if-changed={bindings}");
    std::fs::copy(&bindings, out).expect("could not copy the FFmpeg bindings");
}
